const input = $json.body || $json;
const resourceName = String(input.resource_name || '').trim();
const updates = input.updates;
const allowedFields = new Set([
  'addresses', 'biographies', 'birthdays', 'calendarUrls', 'clientData',
  'emailAddresses', 'events', 'externalIds', 'genders', 'imClients',
  'interests', 'locales', 'locations', 'memberships', 'miscKeywords',
  'names', 'nicknames', 'occupations', 'organizations', 'phoneNumbers',
  'relations', 'sipAddresses', 'urls', 'userDefined'
]);

if (!/^people\/[^/]+$/.test(resourceName)) {
  return [{ json: { error: true, message: "resource_name doit être un identifiant people/... obtenu depuis Google Contacts." } }];
}
if (!updates || typeof updates !== 'object' || Array.isArray(updates)) {
  return [{ json: { error: true, message: "updates doit être un objet contenant les champs à modifier." } }];
}
const fields = Object.keys(updates);
if (fields.length === 0) {
  return [{ json: { error: true, message: 'Au moins un champ à modifier est requis.' } }];
}
const unsupported = fields.filter(field => !allowedFields.has(field));
if (unsupported.length) {
  return [{ json: { error: true, message: `Champ(s) non modifiable(s) par Google People API : ${unsupported.join(', ')}.` } }];
}
if (fields.some(field => updates[field] === null)) {
  return [{ json: { error: true, message: 'Utilise une valeur complète ou une liste vide pour effacer un champ, pas null.' } }];
}

return [{ json: { resource_name: resourceName, updates, update_person_fields: fields.join(',') } }];

const request = $('Valider la demande').first().json;
const current = $json;
const etag = current.etag || current.metadata?.sources?.find(source => source.type === 'CONTACT')?.etag;

if (!etag) {
  return [{ json: { error: true, message: "Impossible de récupérer l'ETag du contact; aucune modification n'a été envoyée." } }];
}

return [{
  json: {
    resource_name: request.resource_name,
    update_person_fields: request.update_person_fields,
    person: { resourceName: request.resource_name, etag, ...request.updates }
  }
}];
